// Some portions generated by Claude
package org.eclipse.rdf4j.repository.sail;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryResolver;
import org.junit.jupiter.api.Test;

class ProxyRepositoryTest {

	@Test
	void shuttingDownTheProxyLeavesTheResolverOwnedTargetRunning() {
		Repository target = mock(Repository.class);
		when(target.isInitialized()).thenReturn(true);
		RepositoryResolver resolver = mock(RepositoryResolver.class);
		when(resolver.getRepository("main")).thenReturn(target);
		ProxyRepository proxy = new ProxyRepository(resolver, "main");
		proxy.init();

		proxy.shutDown();

		// The resolver (a repository manager) owns the target; restarting or removing a proxy must not stop it.
		verify(target, never()).shutDown();
	}
}
